namespace {
class DocumentConformanceMetaEnum final : public ExyokiOffice::OpenXmlMetaEnum
{
public:
    ExyokiOffice::OpenXmlQualifiedName TypeQualifiedName() const noexcept override
    {
        return ExyokiOffice::OpenXmlQualifiedName("http://schemas.openxmlformats.org/wordprocessingml/2006/main", "ST_DocumentConformance");
    }

    ExyokiOffice::OpenXml::FileFormatVersions GetVersion() const noexcept override
    {
        return ExyokiOffice::OpenXml::FileFormatVersions::Office2007;
    }

    ExyokiOffice::OpenXml::FileFormatVersions GetVersionForEnumValue(ExyokiOffice::UInt32 rawValue) const noexcept override
    {
        (void)rawValue;
        return ExyokiOffice::OpenXml::FileFormatVersions::Office2007;
    }

    std::string_view ToString(ExyokiOffice::UInt32 rawValue) const override
    {
        switch (static_cast<DocumentConformance::Value>(rawValue))
        {
            case DocumentConformance::NotDefinedEnumValue:
            case DocumentConformance::InvalidEnumValue:
                return std::string_view();
            case DocumentConformance::transitional:
                return "transitional";
            case DocumentConformance::strict:
                return "strict";
            default:
                return std::string_view();
        }
    }

    ExyokiOffice::UInt32 FromString(std::string_view value) const override
    {
        constexpr std::array<std::pair<std::string_view, DocumentConformance::Value>, 2> kValidValues = {
            std::make_pair("transitional", DocumentConformance::transitional),
            std::make_pair("strict", DocumentConformance::strict),
        };

        for (const auto& [text, enumValue] : kValidValues)
        {
            if (text == value)
            {
                return static_cast<ExyokiOffice::UInt32>(enumValue);
            }
        }

        return static_cast<ExyokiOffice::UInt32>(DocumentConformance::InvalidEnumValue);
    }
};
} // namespace

const ExyokiOffice::OpenXmlMetaEnum* DocumentConformance::GetMetaEnum() noexcept
{
    static const DocumentConformanceMetaEnum kMeta{};
    return &kMeta;
}

